const $=s=>document.querySelector(s);let state={stars:0,done:[],palette:'Earth',best:{}};try{const s=JSON.parse(localStorage.getItem('epa-v1'));if(s&&Array.isArray(s.done))state={...state,...s}}catch{}let tab='explore',timers=[],playing=false,expected=[],hits=0,index=0,audio;const stop=()=>{timers.forEach(clearTimeout);timers=[];playing=false};function later(fn,ms){timers.push(setTimeout(fn,ms))}function save(){try{localStorage.setItem('epa-v1',JSON.stringify(state))}catch{}}function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3000)}function unity(){return Math.min(100,state.done.length*20)}function update(){document.body.dataset.palette=state.palette;document.body.classList.toggle('large-text',!!state.largeText);document.body.classList.toggle('reduce-motion',!!state.reduceMotion);const player=document.querySelector('.player');player.replaceChildren();const av=document.createElement('span');av.textContent=state.avatar||'☀';const info=document.createElement('div');info.textContent=state.name||'Welcome, festival maker';const sub=document.createElement('small');sub.textContent='CHAPTER 01 · THE HOMECOMING';info.append(sub);player.append(av,info);save();$('#stars').textContent=state.stars+' ✦';$('#unity').textContent=unity()+'%';$('#meter').value=unity();$('#finale').disabled=unity()<100;$('#finale').textContent=unity()<100?'Grand celebration 🔒':'Join the grand celebration ✦';$('#decor').textContent=['🌳 🛖 🥁 🌳','🌳 🛖 🎏 🥁 🌳','🌺 🎏 🛖 🥁 🌳','🌺 🏮 🎏 🥁 🌳','🌺 🏮 🎏 🥁 🎊','🌺 🏮 🎏 🥁 🎊 🎉'][Math.min(5,state.done.length)];$('#stage').textContent=unity()<100?`Your ${state.palette.toLowerCase()} square is growing. ${state.done.length} of 5 community milestones complete.`:'The community is ready. Let the celebration begin!'}function award(id,n){state.stars+=n;if(!state.done.includes(id))state.done.push(id);update();toast('+'+n+' Heritage Stars · '+unity()+'% Community Unity')}function modal(html){$('#modalbody').innerHTML=html;$('#modal').showModal()}const culture=()=>modal('<p class="eyebrow">OUR CULTURAL PROMISE</p><h2>Created with care.</h2><p>This is a fictional adventure inspired by the idea of preparing a community celebration in Oro-Ago. Characters, challenges, rhythm patterns, and illustrations are invented for this prototype.</p><p>Costumes, stories, music, and masquerade depictions require review by Oro-Ago cultural custodians before being described as authentic. Sacred rites are outside this game. No masquerade ritual is simulated.</p><p>Progress and best scores stay in this browser. Online multiplayer and a full 3D world are planned, not included in this version.</p>');$('#about').onclick=culture;$('#culture').onclick=culture;$('#close').onclick=()=>$('#modal').close();$('#start').onclick=()=>{$('#adventure').scrollIntoView({behavior:'smooth'});render('explore')};$('#reset').onclick=()=>{modal('<h2>Start a fresh adventure?</h2><p>This removes stars, unlocked decorations, and scores saved on this device.</p><button class="primary" id="confirmReset">Reset progress</button>');$('#confirmReset').onclick=()=>{stop();state={stars:0,done:[],palette:'Earth',best:{}};update();render('explore');$('#modal').close()}};
function render(t){stop();tab=t;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===t));const p=$('#panel');if(t==='explore'){p.innerHTML='<p class="eyebrow">DISCOVER YOUR NEIGHBORS</p><h3>Every celebration starts with a hello.</h3><p>Visit three fictional community characters. Collect all their story cards to complete your exploration milestone.</p><div class="options">'+[['elder','🌳','The storyteller','A place for every voice'],['artisan','🧵','The artisan','Made by many hands'],['drummer','🥁','The drummer','Listen, then join in']].map(([id,icon,name,desc])=>`<button class="option" data-story="${id}"><span>${icon}</span>${name}<small>${desc} ${state['card_'+id]?'✓':''}</small></button>`).join('')+'</div>';document.querySelectorAll('[data-story]').forEach(b=>b.onclick=()=>{const id=b.dataset.story;state['card_'+id]=true;save();modal('<p class="eyebrow">FICTIONAL STORY CARD</p><h2>'+({elder:'A place for every voice',artisan:'Made by many hands',drummer:'Listen, then join in'}[id])+'</h2><p>'+({elder:'“A square feels like home when everyone has a place in it.” Invite a neighbor into your next activity.',artisan:'“A bright decoration begins with a small, careful stitch.” Creativity grows through patience and shared effort.',drummer:'“Before you play your part, listen to the people around you.” A shared beat begins with attention.'}[id])+'</p>');if(['elder','artisan','drummer'].every(x=>state['card_'+x])&&!state.done.includes('explore'))award('explore',30);render('explore')})}
if(t==='prepare'){p.innerHTML='<p class="eyebrow">SMALL ACTS. SHARED JOY.</p><h3>Everyone has a part to play.</h3><p>Choose the best way to help each neighbor prepare the square.</p><div class="options">'+[['flags','🎏','Hang the flags'],['paths','🧹','Clear the paths'],['welcome','🤝','Welcome the guests']].map(([id,icon,name])=>`<button class="option" data-mission="${id}"><span>${icon}</span>${name}<small>${state['mission_'+id]?'Completed ✓':'Begin mission →'}</small></button>`).join('')+'</div>';document.querySelectorAll('[data-mission]').forEach(b=>b.onclick=()=>{const id=b.dataset.mission;const questions={flags:['Where should the flags go?','Across a safe, open display area','Across the walking path'],paths:['How can we make arrival easier?','Leave supplies in the entrance','Keep the entrance clear'],welcome:['A new visitor arrives. What do you do?','Show them around and introduce a neighbor','Tell them to find their own way']};const q=questions[id];modal(`<h2>${q[0]}</h2><div class="options"><button class="option" data-answer="0">${q[1]}</button><button class="option" data-answer="1">${q[2]}</button></div>`);document.querySelectorAll('[data-answer]').forEach(a=>a.onclick=()=>{if(+a.dataset.answer===({flags:0,paths:1,welcome:0}[id])){state['mission_'+id]=true;save();$('#modal').close();if(['flags','paths','welcome'].every(x=>state['mission_'+x])&&!state.done.includes('prepare'))award('prepare',30);else toast('Neighbor helped ✓');render('prepare')}else toast('Think about safety and including everyone. Try again.')})})}
if(t==='workshop'){p.innerHTML='<p class="eyebrow">THE ARTISAN WORKSHOP</p><h3>Color your corner of the square.</h3><p>Choose an invented design palette. Your choice is saved and completes the artisan milestone.</p><div class="options">'+[['Earth','🟠','Terracotta · sand · forest'],['Sunshine','🟡','Gold · cream · leaf'],['Twilight','🟣','Plum · coral · indigo']].map(([name,icon,desc])=>`<button class="option" data-palette="${name}"><span>${icon}</span>${name}<small>${desc}${state.palette===name?' ✓':''}</small></button>`).join('')+'</div>';document.querySelectorAll('[data-palette]').forEach(b=>b.onclick=()=>{state.palette=b.dataset.palette;if(!state.done.includes('workshop'))award('workshop',20);update();render('workshop')})}
if(t==='drum'||t==='dance'){const dance=t==='dance';p.innerHTML=`<p class="eyebrow">${dance?'MOVE WITH THE MUSIC':'FIND YOUR RHYTHM'}</p><h3>${dance?'Step into the celebration.':'One beat brings us together.'}</h3><p>${dance?'Watch the arrow and press the matching arrow key or button':'Listen to the count-in, then tap the drum or press Space when each circle lights up'}. Get at least 4 of 8 to complete this milestone. Best: ${state.best[t]||0}/8.</p><div class="beat">${Array.from({length:8},(_,i)=>`<span class="note" id="n${i}">${i+1}</span>`).join('')}</div><div class="status" role="status" id="status">Ready when you are.</div><div class="pads">${dance?['←','↑','→'].map((x,i)=>`<button class="pad" data-hit="${i}" aria-label="${['Left','Up','Right'][i]}">${x}</button>`).join(''):'<button class="pad" data-hit="0" aria-label="Tap drum">🥁</button>'}</div><button class="primary" id="play">Start ${dance?'dance':'drum'} challenge</button>`;$('#play').onclick=()=>challenge(dance);document.querySelectorAll('[data-hit]').forEach(b=>b.onclick=()=>hit(+b.dataset.hit))}}
let windowOpen=false,used=false;function sound(freq){try{audio ||=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.setValueAtTime(freq,audio.currentTime);o.frequency.exponentialRampToValueAtTime(60,audio.currentTime+.12);g.gain.setValueAtTime(.15,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.15);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+.16)}catch{}}
function challenge(dance){stop();playing=true;hits=0;index=-1;windowOpen=false;$('#play').disabled=true;expected=Array.from({length:8},()=>dance?Math.floor(Math.random()*3):0);for(let c=0;c<3;c++)later(()=>{$('#status').textContent='Get ready… '+(3-c);sound(180)},c*600);for(let i=0;i<8;i++){later(()=>{document.querySelectorAll('.note').forEach(n=>n.classList.remove('on'));index=i;used=false;windowOpen=true;$('#n'+i).classList.add('on');$('#status').textContent=dance?['← LEFT','↑ UP','→ RIGHT'][expected[i]]:'TAP!';sound(250)},2000+i*850);later(()=>{windowOpen=false;$('#n'+i)?.classList.remove('on')},(state.difficulty==='Hard'?2300:state.difficulty==='Easy'?2700:2550)+i*850)}later(()=>{playing=false;windowOpen=false;state.best[tab]=Math.max(state.best[tab]||0,hits);save();$('#status').textContent=`${hits}/8 · ${hits>=4?'Wonderful! Milestone complete.':'Keep practicing — try again!'}`;$('#play').disabled=false;if(hits>=4)award(tab,hits*5)},9000)}function hit(n){if(!playing||!windowOpen||used)return;used=true;if(expected[index]===n){hits++;$('#status').textContent='Beautiful! ✦';sound(350)}else $('#status').textContent='Try the next beat.'}document.addEventListener('keydown',e=>{if($('#modal').open)return;if(tab==='drum'&&e.code==='Space'&&playing){e.preventDefault();hit(0)}if(tab==='dance'&&playing){const k={ArrowLeft:0,ArrowUp:1,ArrowRight:2}[e.key];if(k!==undefined){e.preventDefault();hit(k)}}});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>render(b.dataset.tab));$('#finale').onclick=()=>{if(unity()<100)return;sound(300);modal('<p class="eyebrow">THE GRAND CELEBRATION</p><h2>You brought the community together! 🎉</h2><p>The flags are flying, the paths are clear, and your neighbors are ready. Your listening, creativity, and care filled the Community Unity meter.</p><p><strong>'+state.stars+' Heritage Stars · 100% Community Unity</strong></p><p>Keep playing to improve your rhythm and dance scores, or let a friend take a turn on this device.</p>')};update();render('explore');

$('#settings').onclick=()=>{modal(`<p class="eyebrow">MAKE YOURSELF AT HOME</p><h2>Your festival maker.</h2><label>Player name <input id="playername" maxlength="30" autocomplete="nickname"></label><p><label>Avatar <select id="avatar"><option>☀</option><option>🌟</option><option>🎨</option><option>🥁</option><option>🌺</option></select></label> <label>Clothing palette <select id="outfit"><option>Earth</option><option>Sunshine</option><option>Twilight</option></select></label></p><p><label>Rhythm difficulty <select id="difficulty"><option>Easy</option><option>Normal</option><option>Hard</option></select></label></p><p><label><input type="checkbox" id="large"> Larger text</label> <label><input type="checkbox" id="motion"> Reduced motion</label></p><button class="primary" id="savesettings">Save player</button><p><button id="tutorial">How to play</button> <button id="backup">Export save</button></p><label>Restore a save backup <input type="file" accept="application/json,.json" id="restore"></label><p id="restorestatus" role="status"></p><p>English interface. Yoruba translation awaits fluent-speaker review. Saves remain on this device; export a backup before clearing browser data.</p>`);$('#playername').value=state.name||'';$('#avatar').value=state.avatar||'☀';$('#outfit').value=state.palette;$('#difficulty').value=state.difficulty||'Normal';$('#large').checked=!!state.largeText;$('#motion').checked=!!state.reduceMotion;$('#savesettings').onclick=()=>{state.name=$('#playername').value.trim();state.avatar=$('#avatar').value;state.palette=$('#outfit').value;state.difficulty=$('#difficulty').value;state.largeText=$('#large').checked;state.reduceMotion=$('#motion').checked;update();$('#modal').close();toast('Player settings saved')};$('#tutorial').onclick=tutorial;$('#backup').onclick=()=>{const blob=new Blob([JSON.stringify({version:1,save:state},null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='epa-adventure-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};$('#restore').onchange=async e=>{try{const f=e.target.files[0];if(!f||f.size>50000)throw Error();const data=JSON.parse(await f.text()),v=data.save;if(data.version!==1||!v||!Number.isFinite(v.stars)||v.stars<0||v.stars>10000000||!Array.isArray(v.done)||v.done.some(x=>!['explore','prepare','workshop','drum','dance'].includes(x)))throw Error();const clean={stars:Math.floor(v.stars),done:[...new Set(v.done)],palette:['Earth','Sunshine','Twilight'].includes(v.palette)?v.palette:'Earth',best:{},name:typeof v.name==='string'?v.name.slice(0,30):'',avatar:['☀','🌟','🎨','🥁','🌺'].includes(v.avatar)?v.avatar:'☀',difficulty:['Easy','Normal','Hard'].includes(v.difficulty)?v.difficulty:'Normal',largeText:!!v.largeText,reduceMotion:!!v.reduceMotion};for(const k of ['drum','dance'])clean.best[k]=Math.max(0,Math.min(8,Math.floor(Number(v.best?.[k])||0)));for(const k of ['card_elder','card_artisan','card_drummer','mission_flags','mission_paths','mission_welcome'])clean[k]=!!v[k];stop();state=clean;update();render('explore');$('#modal').close();toast('Adventure restored')}catch{$('#restorestatus').textContent='This is not a valid Epa save backup. Your current progress is unchanged.'}}};
function tutorial(){modal('<p class="eyebrow">YOUR FIRST STEPS</p><h2>Five ways to bring us together.</h2><p>1. Explore: visit all three neighbors to collect fictional story cards.</p><p>2. Prepare: help with flags, paths, and welcoming visitors.</p><p>3. Workshop: choose your square’s color palette.</p><p>4. Drum: after the countdown, tap when a numbered circle lights up. Keyboard: Space.</p><p>5. Dance: match the displayed arrow using the large buttons or Left, Up, and Right keys.</p><p>Score 4 of 8 in each challenge. Complete all five milestones to unlock the celebration. You can practice as often as you like.</p>')}
